package com.crmconnect.dealflow;
import com.crmconnect.common.BaseEntity; import jakarta.persistence.*; import org.hibernate.annotations.Filter;
import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="deal_flows") @Filter(name="tenantFilter",condition="tenant_id = :tenantId") public class DealFlow extends BaseEntity {private Long tenantId,connectionId,assignedToUserId;private String title;private BigDecimal amount;@Enumerated(EnumType.STRING) private Stage stage=Stage.NEW;private LocalDate expectedCloseDate;public enum Stage{NEW,CONTACTED,PROPOSAL,NEGOTIATION,WON,LOST}public Long getTenantId(){return tenantId;}public void setTenantId(Long v){tenantId=v;}public Long getConnectionId(){return connectionId;}public void setConnectionId(Long v){connectionId=v;}public Long getAssignedToUserId(){return assignedToUserId;}public void setAssignedToUserId(Long v){assignedToUserId=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public Stage getStage(){return stage;}public void setStage(Stage v){stage=v;}public LocalDate getExpectedCloseDate(){return expectedCloseDate;}public void setExpectedCloseDate(LocalDate v){expectedCloseDate=v;}}
